/* =========================================================================
   WEB AUDIO API
   ========================================================================= */
class AudioEngine {
  constructor() {
    this.ctx = null;
    this.muted = false;
  }
  ensureContext() {
    if (!this.ctx) {
      const AudioContext = window.AudioContext || window.webkitAudioContext;
      this.ctx = new AudioContext();
    }
    if (this.ctx.state === 'suspended') {
      this.ctx.resume();
    }
  }
  playBlip(freq = 520, duration = 0.04, type = 'sine') {
    if (this.muted) return;
    this.ensureContext();
    try {
      const osc = this.ctx.createOscillator();
      const gain = this.ctx.createGain();
      osc.type = type;
      osc.frequency.setValueAtTime(freq, this.ctx.currentTime);
      gain.gain.setValueAtTime(0.08, this.ctx.currentTime);
      gain.gain.exponentialRampToValueAtTime(0.0001, this.ctx.currentTime + duration);
      osc.connect(gain);
      gain.connect(this.ctx.destination);
      osc.start();
      osc.stop(this.ctx.currentTime + duration);
    } catch (e) {}
  }
  playMetronomeClick() {
    if (this.muted) return;
    this.ensureContext();
    try {
      const osc = this.ctx.createOscillator();
      const gain = this.ctx.createGain();
      osc.type = 'triangle';
      osc.frequency.setValueAtTime(1050, this.ctx.currentTime);
      gain.gain.setValueAtTime(0.15, this.ctx.currentTime);
      gain.gain.exponentialRampToValueAtTime(0.001, this.ctx.currentTime + 0.025);
      osc.connect(gain);
      gain.connect(this.ctx.destination);
      osc.start();
      osc.stop(this.ctx.currentTime + 0.025);
    } catch (e) {}
  }
  playError() {
    if (this.muted) return;
    this.playBlip(140, 0.18, 'sawtooth');
  }
  playFanfare() {
    if (this.muted) return;
    [523.25, 659.25, 783.99, 1046.5].forEach((f, i) => {
      setTimeout(() => this.playBlip(f, 0.12, 'sine'), i * 85);
    });
  }
  toggleMute() {
    this.muted = !this.muted;
    const onIcon = document.getElementById('soundIconOn');
    const offIcon = document.getElementById('soundIconOff');
    if (onIcon) onIcon.classList.toggle('hidden', this.muted);
    if (offIcon) offIcon.classList.toggle('hidden', !this.muted);
    uiHelpers.toast(this.muted ? "Дыбыс өшірілді 🔇" : "Дыбыс қосылды 🔊");
  }
}
const audioEngine = new AudioEngine();

/* =========================================================================
   MODALS & ROUTER (НАВИГАЦИЯ ЖӘНЕ ТЕРЕЗЕЛЕР)
   ========================================================================= */
const modals = {
  open(id) {
    const el = document.getElementById(id);
    if (el) el.classList.remove('hidden');
  },
  close(id) {
    const el = document.getElementById(id);
    if (el) el.classList.add('hidden');
  }
};

const router = {
  navigate(routeId) {
    if (rsvpEngine.isPlaying) rsvpEngine.pause();
    if (pacerEngine.pacerActive) pacerEngine.togglePacer();

    appState.currentRoute = routeId;
    document.querySelectorAll('.app-module').forEach(m => m.classList.add('hidden'));
    const target = document.getElementById(`module-${routeId}`);
    if (target) target.classList.remove('hidden');

    document.querySelectorAll('.nav-link').forEach(btn => {
      btn.className = 'nav-link px-3 py-1.5 rounded-xl text-xs font-medium flex items-center gap-2 text-slate-300 hover:text-white hover:bg-slate-800/60';
    });
    const activeNav = document.getElementById(`nav-${routeId}`);
    if (activeNav) {
      activeNav.className = 'nav-link px-3 py-1.5 rounded-xl text-xs font-semibold flex items-center gap-2 text-white bg-brand-600 shadow-md';
    }

    ['rsvp', 'schulte', 'saccade', 'pacer', 'diagnostic', 'analytics'].forEach(id => {
      const mobBtn = document.getElementById(`mob-${id}`);
      if (mobBtn) {
        mobBtn.className = id === routeId
          ? 'flex flex-col items-center gap-1 text-brand-400 font-bold p-1'
          : 'flex flex-col items-center gap-1 text-slate-400 p-1';
      }
    });

    if (routeId === 'schulte' && !schulteEngine.active) schulteEngine.startNewGame();
    if (routeId === 'saccade') saccadeEngine.init();
    if (routeId === 'pacer') pacerEngine.init();
    if (routeId === 'diagnostic') diagnosticEngine.init();
    if (routeId === 'analytics') analyticsManager.fetchFromSupabase();
  }
};

/* =========================================================================
   UI HELPERS & PERFORMANCE-BASED XP/LEVEL SYSTEM
   ========================================================================= */
const uiHelpers = {
  toast(msg, isSuccess = true) {
    const el = document.getElementById('toastNotification');
    const txt = document.getElementById('toastMessage');
    const icon = document.getElementById('toastIcon');
    if (!el || !txt || !icon) return;
    txt.innerText = msg;
    icon.innerText = isSuccess ? '✓' : '⚠️';
    icon.className = isSuccess
      ? 'w-7 h-7 rounded-xl bg-emerald-500/20 text-emerald-400 flex items-center justify-center font-bold'
      : 'w-7 h-7 rounded-xl bg-rose-500/20 text-rose-400 flex items-center justify-center font-bold';
    el.classList.remove('translate-x-32', 'opacity-0');
    setTimeout(() => el.classList.add('translate-x-32', 'opacity-0'), 3500);
  },

  addXP(amount, reason = "") {
    if (amount <= 0) return;
    appState.user.xp += amount;

    let leveledUp = false;
    while (appState.user.xp >= appState.user.level * 250) {
      appState.user.xp -= appState.user.level * 250;
      appState.user.level++;
      leveledUp = true;
    }

    if (appState.currentUser) {
      appState.currentUser.xp = appState.user.xp;
      appState.currentUser.level = appState.user.level;
      localStorage.setItem('neuroread_current_user', JSON.stringify(appState.currentUser));
    }

    if (leveledUp) {
      this.toast(`🎉 ЖАҢА ДЕҢГЕЙ! Сіз L${appState.user.level} деңгейіне көтерілдіңіз!`, true);
      audioEngine.playFanfare();
      confetti({ particleCount: 90, spread: 80, origin: { y: 0.25 } });
    } else if (reason) {
      this.toast(`${reason} (+${amount} XP)`, true);
    }

    storageManager.save();
    this.renderXP();
  },

  renderXP() {
    const target = appState.user.level * 250;
    const badge = document.getElementById('badgeUserLevel');
    const text = document.getElementById('userXpText');
    const bar = document.getElementById('userXpBar');
    const rankLabel = document.getElementById('headerRankLabel');
    const headerSub = document.getElementById('headerUserEmail');

    if (badge) badge.innerText = `L${appState.user.level}`;
    if (text) text.innerText = `${appState.user.xp} / ${target} XP`;
    const pct = Math.min(100, Math.round((appState.user.xp / target) * 100));
    if (bar) bar.style.width = `${pct}%`;

    let rank = 'Junior Reader';
    if (appState.user.level >= 2) rank = 'Algorithmist';
    if (appState.user.level >= 4) rank = 'Code Reader';
    if (appState.user.level >= 6) rank = 'Cyber-Scholar';
    if (appState.user.level >= 9) rank = 'AI Architect';
    appState.user.rank = rank;

    if (rankLabel) rankLabel.innerText = rank;
    if (headerSub && appState.currentUser) {
      headerSub.innerText = `L${appState.user.level} • ${appState.user.xp} XP`;
    }
  }
};

/* =========================================================================
   AUTH MANAGER (SUPABASE AUTH + ШЫНАЙЫ ПРОФИЛЬ)
   ========================================================================= */
const authManager = {
  selectedAvatar: '👩‍💻',
  avatars: ['👩‍💻', '👨‍💻', '👨‍🚀', '👩‍🔬', '⚡', '🧠', '🦉', '🎯', '🚀', '🌟', '🤖', '🦁'],

  init() {
    const container = document.getElementById('avatarSelector');
    if (container) {
      container.innerHTML = this.avatars.map((av, idx) => `
        <button type="button" onclick="authManager.pickAvatar('${av}', this)" class="avatar-btn text-xl p-2 rounded-xl border ${idx === 0 ? 'border-brand-500 bg-brand-500/20' : 'border-slate-800 bg-slate-950'} hover:border-brand-500 transition">
          ${av}
        </button>
      `).join('');
    }

    const storedUser = localStorage.getItem('neuroread_current_user');
    if (storedUser) {
      try {
        appState.currentUser = JSON.parse(storedUser);
        this.applyLoggedInUser(appState.currentUser);
        modals.close('authModal');
      } catch (e) {
        this.showAuthModal();
      }
    } else {
      this.showAuthModal();
    }
  },

  pickAvatar(av, btn) {
    this.selectedAvatar = av;
    document.querySelectorAll('.avatar-btn').forEach(b => {
      b.className = 'avatar-btn text-xl p-2 rounded-xl border border-slate-800 bg-slate-950 hover:border-brand-500 transition';
    });
    btn.className = 'avatar-btn text-xl p-2 rounded-xl border border-brand-500 bg-brand-500/20 transition';
  },

  showAuthModal() {
    const m = document.getElementById('authModal');
    if (m) m.classList.remove('hidden');
  },

  switchTab(tab) {
    const isSignIn = tab === 'signin';
    document.getElementById('tabBtnSignIn').className = isSignIn ? 'flex-1 py-2.5 rounded-xl bg-brand-600 text-white shadow-md transition' : 'flex-1 py-2.5 rounded-xl text-slate-400 hover:text-white transition';
    document.getElementById('tabBtnSignUp').className = !isSignIn ? 'flex-1 py-2.5 rounded-xl bg-brand-600 text-white shadow-md transition' : 'flex-1 py-2.5 rounded-xl text-slate-400 hover:text-white transition';
    document.getElementById('formSignIn').classList.toggle('hidden', !isSignIn);
    document.getElementById('formSignUp').classList.toggle('hidden', isSignIn);
  },

  async handleSignIn(e) {
    if (e) e.preventDefault();
    const ident = document.getElementById('loginIdentifier').value.trim();
    const pass = document.getElementById('loginPassword').value;

    if (supabaseClient) {
      const { data, error } = await supabaseClient.auth.signInWithPassword({ email: ident, password: pass });
      if (!error && data?.user) {
        const u = data.user;
        const userProfile = {
          id: u.id,
          name: u.user_metadata?.full_name || u.email.split('@')[0],
          email: u.email,
          avatar: u.user_metadata?.avatar || '👩‍💻',
          level: appState.user.level || 1,
          xp: appState.user.xp || 0,
          maxWPM: appState.user.maxWPM || 0,
          ers: appState.user.ers || 0
        };
        this.completeLogin(userProfile, 'Жүйеге сәтті кірдіңіз!');
        return;
      }
    }

    const fallbackUser = {
      id: 'u-' + Date.now().toString().slice(-4),
      name: ident.split('@')[0],
      email: ident,
      avatar: '👨‍💻',
      level: 1,
      xp: 0,
      maxWPM: 0,
      ers: 0
    };
    this.completeLogin(fallbackUser, 'Жүйеге сәтті кірдіңіз!');
  },

  async handleSignUp(e) {
    if (e) e.preventDefault();
    const fullName = document.getElementById('regFullName').value.trim();
    const email = document.getElementById('regEmail').value.trim();
    const password = document.getElementById('regPassword').value;

    if (password.length < 6) {
      audioEngine.playError();
      uiHelpers.toast("Құпиясөз кемінде 6 символ болуы керек!", false);
      return;
    }

    if (supabaseClient) {
      await supabaseClient.auth.signUp({
        email,
        password,
        options: { data: { full_name: fullName, avatar: this.selectedAvatar } }
      }).catch(() => {});
    }

    const newUser = {
      id: 'u-' + Date.now().toString().slice(-4),
      name: fullName,
      email: email,
      avatar: this.selectedAvatar,
      level: 1,
      xp: 50,
      maxWPM: 0,
      ers: 0
    };
    this.completeLogin(newUser, 'Тіркелу сәтті аяқталды! +50 бастапқы XP берілді.');
  },

  loginAsGuest() {
    const guestUser = {
      id: 'guest-' + Math.floor(100 + Math.random() * 900),
      name: 'Қонақ Оқушы',
      email: 'guest@neuroread.kz',
      avatar: '🚀',
      level: 1,
      xp: 0,
      maxWPM: 0,
      ers: 0
    };
    this.completeLogin(guestUser, 'Демо-режим іске қосылды!');
  },

  completeLogin(user, toastMsg) {
    appState.currentUser = user;
    appState.user.level = user.level || 1;
    appState.user.xp = user.xp || 0;
    appState.user.maxWPM = user.maxWPM || 0;
    appState.user.ers = user.ers || 0;

    localStorage.setItem('neuroread_current_user', JSON.stringify(user));
    this.applyLoggedInUser(user);

    modals.close('authModal');
    uiHelpers.toast(toastMsg, true);
    audioEngine.playFanfare();

    // Нақты кіруді Supabase базасына жазу
    analyticsManager.recordRealActivity('🚀 Жүйеге кірді', appState.user.maxWPM, appState.user.ers, 100);
  },

  applyLoggedInUser(user) {
    const avatarEl = document.getElementById('headerUserAvatar');
    const nameEl = document.getElementById('headerUserName');
    if (avatarEl) avatarEl.innerText = user.avatar || '👨‍💻';
    if (nameEl) nameEl.innerText = user.name;
    uiHelpers.renderXP();
  },

  async logout() {
    if (supabaseClient) await supabaseClient.auth.signOut().catch(() => {});
    localStorage.removeItem('neuroread_current_user');
    appState.currentUser = null;
    this.showAuthModal();
  },

  detectDevice() {
    const ua = navigator.userAgent;
    if (/android/i.test(ua)) return 'Android • Mobile';
    if (/iPhone|iPad|iPod/i.test(ua)) return 'iOS • Safari';
    if (/Macintosh/i.test(ua)) return 'macOS • Desktop';
    if (/Windows/i.test(ua)) return 'Windows • Desktop';
    return 'Web Browser';
  },

  showAccountInfo() {
    const u = appState.currentUser || { name: 'Қонақ', email: 'guest@edu.kz', avatar: '👨‍💻' };
    document.getElementById('profileModalAvatar').innerText = u.avatar || '👨‍💻';
    document.getElementById('profileModalName').innerText = u.name;
    document.getElementById('profileModalEmail').innerText = u.email;
    document.getElementById('profileModalRole').innerText = `Rank: ${appState.user.rank}`;
    document.getElementById('profileModalLevel').innerText = `Level ${appState.user.level} (${appState.user.xp} XP)`;
    document.getElementById('profileModalMaxWpm').innerText = `${appState.user.maxWPM} WPM / ${appState.user.ers} ERS`;
    modals.open('accountModal');
  }
};

/* =========================================================================
   REAL-TIME SUPABASE ANALYTICS MANAGER (100% НАҚТЫ ҚОЛДАНУШЫЛАР)
   ========================================================================= */
const analyticsManager = {
  async recordRealActivity(moduleName, wpm = 0, ers = 0, compPct = 100) {
    const u = appState.currentUser || { name: 'Қонақ', email: 'guest@neuroread.kz', avatar: '👨‍💻' };
    const now = new Date();
    const timeStr = now.toLocaleTimeString('ru-RU', { hour: '2-digit', minute: '2-digit' });
    const deviceStr = authManager.detectDevice();

    const entry = {
      name: u.name,
      email: u.email,
      avatar: u.avatar || '👨‍💻',
      module: moduleName,
      time: `Бүгін, ${timeStr}`,
      device: deviceStr,
      level: appState.user.level,
      xp: appState.user.xp,
      wpm: wpm || 0,
      ers: ers || 0,
      comp: compPct
    };

    appState.loginAuditLogs.unshift(entry);
    storageManager.save();

    if (supabaseClient) {
      try {
        await supabaseClient.from('neuro_sessions').insert([{
          user_name: entry.name,
          user_email: entry.email,
          avatar: entry.avatar,
          module_name: entry.module,
          level: entry.level,
          xp: entry.xp,
          wpm: entry.wpm,
          ers: entry.ers,
          comp_pct: entry.comp,
          device: entry.device
        }]);
        await this.fetchFromSupabase();
        return;
      } catch (err) {}
    }

    this.render();
  },

  async fetchFromSupabase() {
    if (!supabaseClient) {
      this.render();
      return;
    }
    try {
      const { data, error } = await supabaseClient
        .from('neuro_sessions')
        .select('*')
        .order('created_at', { ascending: false })
        .limit(50);

      if (!error && data) {
        appState.loginAuditLogs = data.map(row => {
          const dt = new Date(row.created_at);
          const datePart = dt.toLocaleDateString('ru-RU', { day: '2-digit', month: '2-digit' });
          const timePart = dt.toLocaleTimeString('ru-RU', { hour: '2-digit', minute: '2-digit' });
          return {
            name: row.user_name,
            email: row.user_email,
            avatar: row.avatar || '👨‍💻',
            module: row.module_name || 'Жүйеге кіру',
            time: `${datePart} • ${timePart}`,
            device: row.device || 'Web Browser',
            level: row.level || 1,
            xp: row.xp || 0,
            wpm: row.wpm || 0,
            ers: row.ers || 0,
            comp: row.comp_pct !== null ? row.comp_pct : 100
          };
        });
        storageManager.save();
      }
    } catch (e) {}
    this.render();
  },

  render() {
    const logs = appState.loginAuditLogs || [];
    const uniqueUsersMap = {};

    logs.forEach(l => {
      if (!uniqueUsersMap[l.email] || l.ers > uniqueUsersMap[l.email].ers || l.xp > uniqueUsersMap[l.email].xp) {
        uniqueUsersMap[l.email] = l;
      }
    });
    const uniqueUsersList = Object.values(uniqueUsersMap);

    const vCount = document.getElementById('statVisitorCount');
    const actSess = document.getElementById('statActiveSessions');
    const accTotal = document.getElementById('statAccountsTotal');
    const avgErsEl = document.getElementById('statPlatformAvgWpm');
    const gWords = document.getElementById('statGlobalWords');

    if (vCount) vCount.innerText = logs.length;
    if (actSess) actSess.innerText = `Барлық жазба саны: ${logs.length}`;
    if (accTotal) accTotal.innerText = uniqueUsersList.length;
    if (gWords) gWords.innerText = (appState.user.totalWordsRead || 0).toLocaleString();

    const ersLogs = logs.filter(l => l.ers > 0).map(l => l.ers);
    const avgErs = ersLogs.length > 0
      ? Math.round(ersLogs.reduce((a, b) => a + b, 0) / ersLogs.length)
      : (appState.user.ers || 0);
    if (avgErsEl) avgErsEl.innerHTML = `${avgErs} <span class="text-xs font-normal text-slate-400">ERS</span>`;

    this.renderLeaderboard(uniqueUsersList);
    this.renderAuditTable();
    this.renderDirectoryGrid(uniqueUsersList);
    this.renderSvgChart();
  },

  renderLeaderboard(uniqueUsersList) {
    const box = document.getElementById('topLeaderboardPodium');
    if (!box) return;

    const sorted = [...uniqueUsersList]
      .sort((a, b) => (b.ers || 0) - (a.ers || 0) || (b.xp || 0) - (a.xp || 0))
      .slice(0, 3);

    if (sorted.length === 0) {
      box.innerHTML = `<div class="col-span-3 text-xs text-slate-500 py-8 text-center">Әзірге деректер жоқ. Диагностикадан өтіп, рейтингті бастаңыз!</div>`;
      return;
    }

    const medals = ['🥇 1-ОРЫН', '🥈 2-ОРЫН', '🥉 3-ОРЫН'];
    const colors = [
      'border-amber-500/40 bg-amber-500/10 text-amber-300',
      'border-slate-400/40 bg-slate-800/60 text-slate-200',
      'border-amber-700/40 bg-amber-900/15 text-amber-500'
    ];

    box.innerHTML = sorted.map((u, idx) => `
      <div class="p-4 rounded-2xl border ${colors[idx]} flex flex-col justify-between gap-3">
        <div class="flex items-center justify-between">
          <span class="text-[10px] font-mono font-black uppercase px-2 py-0.5 rounded bg-slate-950/60">${medals[idx]}</span>
          <span class="text-xs font-mono font-bold">L${u.level || 1} • ${u.xp || 0} XP</span>
        </div>
        <div class="flex items-center gap-3">
          <span class="text-3xl">${u.avatar || '👨‍💻'}</span>
          <div class="overflow-hidden">
            <h4 class="font-bold text-sm text-white truncate">${u.name}</h4>
            <span class="text-[10px] font-mono text-slate-400 truncate block">${u.email}</span>
          </div>
        </div>
        <div class="pt-2 border-t border-slate-800/80 flex justify-between items-center font-mono">
          <span class="text-[10px] text-slate-400">Рекорд:</span>
          <span class="text-sm font-black text-cyber-teal">${u.ers || 0} ERS (${u.wpm || 0} WPM)</span>
        </div>
      </div>
    `).join('');
  },

  renderAuditTable() {
    const tbody = document.getElementById('auditTableBody');
    if (!tbody) return;
    const query = (document.getElementById('auditSearchInput')?.value || '').toLowerCase();

    const filtered = (appState.loginAuditLogs || []).filter(l =>
      (l.name || '').toLowerCase().includes(query) ||
      (l.email || '').toLowerCase().includes(query) ||
      (l.module || '').toLowerCase().includes(query)
    );

    if (filtered.length === 0) {
      tbody.innerHTML = `
        <tr>
          <td colspan="6" class="py-8 text-center text-slate-500 text-xs">
            Әзірге жазбалар жоқ. Жүйеге кіріңіз немесе WPM Диагностикасын тапсырыңыз!
          </td>
        </tr>
      `;
      return;
    }

    tbody.innerHTML = filtered.slice(0, 25).map(log => {
      const comp = log.comp !== undefined ? log.comp : 100;
      const barColor = comp >= 80 ? 'bg-emerald-400' : comp >= 50 ? 'bg-amber-400' : 'bg-rose-500';
      return `
        <tr class="hover:bg-slate-900/80 transition">
          <td class="py-3.5 px-4 flex items-center gap-2.5">
            <span class="w-8 h-8 rounded-xl bg-slate-900 border border-slate-800 flex items-center justify-center text-base">${log.avatar || '👨‍💻'}</span>
            <div>
              <div class="font-bold text-white text-xs">${log.name}</div>
              <div class="font-mono text-[10px] text-slate-500">${log.email}</div>
            </div>
          </td>
          <td class="py-3.5 px-4">
            <span class="px-2.5 py-1 rounded-lg bg-slate-900 border border-slate-800 text-slate-200 font-semibold text-[11px]">
              ${log.module || 'Авторизация'}
            </span>
          </td>
          <td class="py-3.5 px-4">
            <div class="text-slate-200 font-medium">${log.time}</div>
            <div class="text-[10px] font-mono text-slate-500">${log.device}</div>
          </td>
          <td class="py-3.5 px-4">
            <span class="px-2.5 py-1 rounded-full text-[10px] font-mono font-bold bg-brand-500/15 text-brand-300 border border-brand-500/30">
              L${log.level || 1} • ${log.xp || 0} XP
            </span>
          </td>
          <td class="py-3.5 px-4 w-32">
            <div class="flex justify-between text-[10px] font-mono mb-1">
              <span>Сапа</span>
              <span class="text-white font-bold">${comp}%</span>
            </div>
            <div class="w-full h-1.5 bg-slate-900 rounded-full overflow-hidden">
              <div class="h-full ${barColor}" style="width: ${comp}%"></div>
            </div>
          </td>
          <td class="py-3.5 px-4 text-right font-mono">
            ${log.wpm > 0
              ? `<span class="text-white font-bold">${log.wpm} WPM</span> <span class="text-slate-500">/</span> <span class="text-cyber-teal font-black">${log.ers} ERS</span>`
              : `<span class="text-slate-400 text-[11px]">Белсенді кіру</span>`
            }
          </td>
        </tr>
      `;
    }).join('');
  },

  renderDirectoryGrid(uniqueUsersList) {
    const grid = document.getElementById('registeredUsersGrid');
    if (!grid) return;
    if (!uniqueUsersList || uniqueUsersList.length === 0) {
      grid.innerHTML = `<div class="col-span-3 text-xs text-slate-500 py-4 text-center">Тіркелген қолданушылар тізімі бос.</div>`;
      return;
    }

    grid.innerHTML = uniqueUsersList.map(u => `
      <div class="bg-slate-950 border border-slate-800 p-4 rounded-2xl flex items-center justify-between hover:border-brand-500/40 transition">
        <div class="flex items-center gap-3">
          <div class="w-11 h-11 rounded-xl bg-slate-900 border border-slate-800 flex items-center justify-center text-xl shadow-inner">
            ${u.avatar || '👨‍💻'}
          </div>
          <div>
            <h4 class="font-bold text-xs text-white leading-none">${u.name}</h4>
            <span class="text-[10px] font-mono text-slate-400">${u.email}</span>
            <span class="block text-[10px] text-cyber-teal font-mono mt-1">${u.time}</span>
          </div>
        </div>
        <div class="text-right">
          <span class="px-2 py-0.5 rounded-md bg-brand-500/15 text-brand-300 text-xs font-mono font-bold">L${u.level || 1}</span>
          <span class="block text-[11px] font-mono font-bold text-white mt-1">${u.ers || 0} ERS</span>
        </div>
      </div>
    `).join('');
  },

  renderSvgChart() {
    const svg = document.getElementById('progressSvgChart');
    if (!svg) return;
    const data = appState.user.wpmHistory || [];

    if (data.length === 0) {
      svg.innerHTML = `<text x="350" y="95" fill="#64748b" font-size="12" font-family="Inter" text-anchor="middle">График шығуы үшін WPM Диагностикасынан кемінде 1 тест тапсырыңыз</text>`;
      return;
    }

    const maxVal = Math.max(400, ...data);
    const minVal = Math.min(50, ...data);
    const range = Math.max(1, maxVal - minVal);
    const width = 700;
    const height = 180;
    const stepX = data.length > 1 ? width / (data.length - 1) : width / 2;

    const points = data.map((val, idx) => ({
      x: data.length > 1 ? idx * stepX : width / 2,
      y: height - ((val - minVal) / range) * (height - 50) - 25,
      val
    }));

    let pathD = `M ${points[0].x} ${points[0].y}`;
    points.slice(1).forEach(pt => { pathD += ` L ${pt.x} ${pt.y}`; });
    let areaD = points.length > 1
      ? `${pathD} L ${points[points.length - 1].x} ${height} L ${points[0].x} ${height} Z`
      : '';

    svg.innerHTML = `
      <defs>
        <linearGradient id="chartGrad" x1="0" y1="0" x2="0" y2="1">
          <stop offset="0%" stop-color="#14b8a6" stop-opacity="0.35"/>
          <stop offset="100%" stop-color="#6366f1" stop-opacity="0.0"/>
        </linearGradient>
      </defs>
      ${areaD ? `<path d="${areaD}" fill="url(#chartGrad)" />` : ''}
      ${points.length > 1 ? `<path d="${pathD}" fill="none" stroke="#14b8a6" stroke-width="3.5" stroke-linecap="round" />` : ''}
      ${points.map((pt, i) => `
        <circle cx="${pt.x}" cy="${pt.y}" r="6" fill="#020617" stroke="#14b8a6" stroke-width="3" />
        <text x="${pt.x}" y="${pt.y - 12}" fill="#ffffff" font-size="11" font-family="JetBrains Mono" text-anchor="middle" font-weight="bold">${pt.val} ERS</text>
        <text x="${pt.x}" y="${height - 4}" fill="#64748b" font-size="10" font-family="JetBrains Mono" text-anchor="middle">Тест #${i + 1}</text>
      `).join('')}
    `;
  },

  exportAuditCsv() {
    let csv = "Name,Email,Module,Time,Device,Level,XP,WPM,ERS,Comprehension%\n";
    appState.loginAuditLogs.forEach(l => {
      csv += `"${l.name}","${l.email}","${l.module}","${l.time}","${l.device}","L${l.level}","${l.xp}","${l.wpm}","${l.ers}","${l.comp}%"\n`;
    });
    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const a = document.createElement('a');
    a.href = URL.createObjectURL(blob);
    a.download = `neuroread_real_analytics_${new Date().toISOString().slice(0, 10)}.csv`;
    a.click();
  }
};

/* =========================================================================
   MODULE 1: SPRITZ RSVP ENGINE
   ========================================================================= */
const rsvpEngine = {
  text: '',
  words: [],
  currentIndex: 0,
  wpm: 350,
  chunkSize: 1,
  showORP: true,
  pausePunctuation: true,
  isPlaying: false,
  timer: null,

  init() {
    this.loadSelectedPreset('algorithms');
  },

  computeORP(word) {
    const len = word.length;
    if (len <= 1) return 0;
    if (len <= 5) return 1;
    if (len <= 9) return 2;
    if (len <= 13) return 3;
    return 4;
  },

  renderCurrent() {
    const leftEl = document.getElementById('spritzLeft');
    const centerEl = document.getElementById('spritzCenter');
    const rightEl = document.getElementById('spritzRight');
    if (!leftEl || !centerEl || !rightEl) return;

    if (this.words.length === 0) {
      leftEl.innerText = 'Бас';
      centerEl.innerText = 'т';
      rightEl.innerText = 'ау';
      return;
    }

    const idx = this.currentIndex;
    const mainWord = this.words[idx] || '';

    if (!this.showORP || mainWord.length === 0) {
      leftEl.innerText = '';
      centerEl.innerText = mainWord;
      rightEl.innerText = '';
    } else {
      const orp = this.computeORP(mainWord);
      leftEl.innerText = mainWord.substring(0, orp);
      centerEl.innerText = mainWord.charAt(orp);

      let rightPart = mainWord.substring(orp + 1);
      if (this.chunkSize > 1) {
        for (let i = 1; i < this.chunkSize; i++) {
          if (this.words[idx + i]) rightPart += ' ' + this.words[idx + i];
        }
      }
      rightEl.innerText = rightPart;
    }

    const total = this.words.length;
    const pct = Math.min(100, Math.round(((idx + 1) / total) * 100));
    const pBar = document.getElementById('spritzProgressBar');
    const pCount = document.getElementById('spritzProgressWordCount');
    const eTime = document.getElementById('spritzEstTime');
    const lWpm = document.getElementById('spritzLiveWPM');

    if (pBar) pBar.style.width = `${pct}%`;
    if (pCount) pCount.innerText = `${idx + 1} / ${total} сөз (${pct}%)`;

    const remainingWords = total - (idx + 1);
    const secRemaining = Math.round((remainingWords / this.wpm) * 60);
    const m = Math.floor(secRemaining / 60);
    const s = secRemaining % 60;
    if (eTime) eTime.innerText = `${String(m).padStart(2, '0')}:${String(s).padStart(2, '0')}`;
    if (lWpm) lWpm.innerText = `${this.wpm} WPM`;
  },

  togglePlay() {
    this.isPlaying ? this.pause() : this.play();
  },

  play() {
    if (this.words.length === 0) this.loadSelectedPreset('algorithms');
    if (this.currentIndex >= this.words.length - 1) this.currentIndex = 0;
    this.isPlaying = true;
    document.getElementById('rsvpPlayBtnText').innerText = "Кідірту (Бос орын)";
    audioEngine.ensureContext();
    this.scheduleNextTick();
  },

  pause() {
    this.isPlaying = false;
    clearTimeout(this.timer);
    document.getElementById('rsvpPlayBtnText').innerText = "Бастау (Бос орын)";
  },

  scheduleNextTick() {
    if (!this.isPlaying) return;
    this.renderCurrent();

    const currentWord = this.words[this.currentIndex] || '';
    let baseDelay = (60 / this.wpm) * 1000 * this.chunkSize;

    if (this.pausePunctuation) {
      if (/[,:;—–\-]/.test(currentWord)) baseDelay *= 1.35;
      if (/[.!?]/.test(currentWord)) baseDelay *= 1.85;
      if (currentWord.length > 10) baseDelay *= 1.15;
    }

    this.timer = setTimeout(() => {
      if (this.currentIndex + this.chunkSize < this.words.length) {
        this.currentIndex += this.chunkSize;
        this.scheduleNextTick();
      } else {
        this.pause();
        this.currentIndex = this.words.length - 1;
        this.renderCurrent();
        appState.user.totalWordsRead += this.words.length;
        if (this.wpm > appState.user.maxWPM) appState.user.maxWPM = this.wpm;
        uiHelpers.addXP(30, "RSVP мәтіні толық оқылды!");
        analyticsManager.recordRealActivity('⚡ RSVP жаттығуы', this.wpm, appState.user.ers, 100);
      }
    }, baseDelay);
  },

  setWPM(val) {
    this.wpm = parseInt(val, 10);
    document.getElementById('spritzWpmNum').innerText = this.wpm;
    document.getElementById('spritzWpmSlider').value = this.wpm;
    document.getElementById('spritzLiveWPM').innerText = `${this.wpm} WPM`;
  },

  skipWords(amount) {
    this.currentIndex = Math.max(0, Math.min(this.words.length - 1, this.currentIndex + amount));
    this.renderCurrent();
  },

  seekTimeline(e) {
    const rect = e.currentTarget.getBoundingClientRect();
    const ratio = Math.max(0, Math.min(1, (e.clientX - rect.left) / rect.width));
    this.currentIndex = Math.floor(ratio * (this.words.length - 1));
    this.renderCurrent();
  },

  setChunk(n) {
    this.chunkSize = n;
    [1, 2, 3].forEach(c => {
      const btn = document.getElementById(`chunkBtn${c}`);
      if (btn) btn.className = c === n ? 'py-2 rounded-xl text-xs font-bold bg-brand-600 text-white shadow' : 'py-2 rounded-xl text-xs font-bold bg-slate-800 text-slate-300 hover:bg-slate-700';
    });
    this.renderCurrent();
  },

  toggleORP(checked) { this.showORP = checked; this.renderCurrent(); },
  togglePunctuation(checked) { this.pausePunctuation = checked; },

  loadSelectedPreset(presetKey) {
    const text = multiLangData.kz.texts[presetKey] || multiLangData.kz.texts.algorithms;
    const select = document.getElementById('rsvpPresetDropdown');
    const badge = document.getElementById('rsvpCurrentTopicBadge');
    if (select && badge && select.selectedOptions[0]) {
      badge.innerText = select.selectedOptions[0].text;
    }
    this.loadRawText(text);
  },

  loadRawText(raw) {
    this.pause();
    this.text = raw.trim();
    this.words = this.text.split(/\s+/).filter(w => w.length > 0);
    this.currentIndex = 0;
    this.renderCurrent();
  },

  applyCustomText() {
    const txt = document.getElementById('customTextInput').value;
    if (txt.trim()) {
      this.loadRawText(txt);
      modals.close('customTextModal');
      uiHelpers.toast("Жеке мәтін сәтті жүктелді!");
    }
  },

  handleFileUpload(e) {
    const file = e.target.files[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      this.loadRawText(event.target.result);
      uiHelpers.toast(`Файл ${file.name} жүктелді!`);
    };
    reader.readAsText(file);
  }
};

/* =========================================================================
   MODULE 2: SCHULTE MATRIX
   ========================================================================= */
const schulteEngine = {
  size: 5,
  mode: 'classic',
  active: false,
  startTime: null,
  timerInterval: null,
  mistakes: 0,
  classicTarget: 1,
  gorbovRedTarget: 1,
  gorbovBlackTarget: 12,
  gorbovNextColor: 'red',
  lettersTargetIndex: 0,
  alphabet: "ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789".split(''),

  setSize(n) {
    this.size = n;
    [3, 4, 5, 6].forEach(s => {
      const btn = document.getElementById(`schulteSize${s}`);
      if (btn) btn.className = s === n ? 'px-3 py-1.5 rounded-xl bg-brand-600 text-white shadow-md' : 'px-3 py-1.5 rounded-xl text-slate-300';
    });
    this.startNewGame();
  },

  setMode(m) {
    this.mode = m;
    ['classic', 'gorbov', 'letters'].forEach(modeKey => {
      const btn = document.getElementById(`schulteMode${modeKey.charAt(0).toUpperCase() + modeKey.slice(1)}`);
      if (btn) btn.className = modeKey === m ? 'px-3 py-1.5 rounded-xl bg-slate-700 text-white' : 'px-3 py-1.5 rounded-xl text-slate-300 hover:text-white';
    });
    this.startNewGame();
  },

  startNewGame() {
    clearInterval(this.timerInterval);
    this.active = true;
    this.startTime = null;
    this.mistakes = 0;
    this.classicTarget = 1;
    this.lettersTargetIndex = 0;

    document.getElementById('schulteMistakeCount').innerText = '0';
    document.getElementById('schulteLiveTimer').innerText = '00.00';

    const colorTag = document.getElementById('schulteTargetColorTag');
    const targetDisplay = document.getElementById('schulteTargetVal');

    if (this.mode === 'gorbov') {
      this.size = 5;
      this.gorbovRedTarget = 1;
      this.gorbovBlackTarget = 12;
      this.gorbovNextColor = 'red';
      colorTag.classList.remove('hidden');
      colorTag.className = 'text-xs px-2 py-0.5 rounded-full font-sans uppercase font-bold bg-rose-500/20 text-rose-400 border border-rose-500/30';
      colorTag.innerText = 'Қызыл ↑';
      targetDisplay.innerText = '1';
    } else if (this.mode === 'letters') {
      colorTag.classList.add('hidden');
      targetDisplay.innerText = this.alphabet[0];
    } else {
      colorTag.classList.add('hidden');
      targetDisplay.innerText = '1';
    }

    this.buildGrid();
  },

  buildGrid() {
    const grid = document.getElementById('schulteGridContainer');
    if (!grid) return;
    grid.innerHTML = '';
    grid.style.gridTemplateColumns = `repeat(${this.size}, minmax(0, 1fr))`;

    const total = this.size * this.size;
    let items = [];

    if (this.mode === 'classic') {
      for (let i = 1; i <= total; i++) items.push({ val: i, display: String(i) });
    } else if (this.mode === 'letters') {
      for (let i = 0; i < total; i++) items.push({ val: i, display: this.alphabet[i % this.alphabet.length] });
    } else if (this.mode === 'gorbov') {
      for (let r = 1; r <= 12; r++) items.push({ val: r, display: String(r), color: 'red' });
      for (let b = 1; b <= 13; b++) items.push({ val: b, display: String(b), color: 'black' });
    }

    for (let i = items.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [items[i], items[j]] = [items[j], items[i]];
    }

    items.forEach(item => {
      const btn = document.createElement('button');
      let cls = 'flex items-center justify-center rounded-2xl font-mono font-bold transition shadow-sm active:scale-95 text-lg sm:text-2xl cursor-pointer ';
      if (this.mode === 'gorbov') {
        cls += item.color === 'red' ? 'bg-rose-950/70 border border-rose-800 text-rose-300 hover:bg-rose-900/60 ' : 'bg-slate-950 border border-slate-800 text-slate-100 hover:bg-slate-800 ';
      } else {
        cls += 'bg-slate-950 border border-slate-800 text-slate-100 hover:bg-slate-800 hover:border-brand-500/50 ';
      }
      btn.className = cls;
      btn.innerText = item.display;
      btn.onclick = () => this.handleCellClick(item, btn);
      grid.appendChild(btn);
    });
  },

  handleCellClick(item, btn) {
    if (!this.active) return;
    if (!this.startTime) {
      this.startTime = performance.now();
      this.timerInterval = setInterval(() => {
        document.getElementById('schulteLiveTimer').innerText = ((performance.now() - this.startTime) / 1000).toFixed(2);
      }, 40);
    }

    let isCorrect = false;
    const total = this.size * this.size;

    if (this.mode === 'classic' && item.val === this.classicTarget) {
      isCorrect = true;
      this.classicTarget++;
      if (this.classicTarget > total) return this.winGame();
      document.getElementById('schulteTargetVal').innerText = this.classicTarget;
    } else if (this.mode === 'letters' && item.val === this.lettersTargetIndex) {
      isCorrect = true;
      this.lettersTargetIndex++;
      if (this.lettersTargetIndex >= total) return this.winGame();
      document.getElementById('schulteTargetVal').innerText = this.alphabet[this.lettersTargetIndex];
    } else if (this.mode === 'gorbov') {
      if (this.gorbovNextColor === 'red' && item.color === 'red' && item.val === this.gorbovRedTarget) {
        isCorrect = true;
        this.gorbovRedTarget++;
        this.gorbovNextColor = 'black';
        this.updateGorbovPrompt();
      } else if (this.gorbovNextColor === 'black' && item.color === 'black' && item.val === this.gorbovBlackTarget) {
        isCorrect = true;
        this.gorbovBlackTarget--;
        this.gorbovNextColor = 'red';
        if (this.gorbovRedTarget > 12 && this.gorbovBlackTarget < 1) return this.winGame();
        this.updateGorbovPrompt();
      }
    }

    if (isCorrect) {
      audioEngine.playBlip(500 + (item.val || 1) * 12, 0.04);
      btn.classList.add('opacity-20', 'pointer-events-none');
    } else {
      audioEngine.playError();
      this.mistakes++;
      document.getElementById('schulteMistakeCount').innerText = this.mistakes;
      btn.classList.add('bg-rose-600/50');
      setTimeout(() => btn.classList.remove('bg-rose-600/50'), 220);
    }
  },

  updateGorbovPrompt() {
    const colorTag = document.getElementById('schulteTargetColorTag');
    const targetDisplay = document.getElementById('schulteTargetVal');
    if (this.gorbovNextColor === 'red') {
      colorTag.className = 'text-xs px-2 py-0.5 rounded-full font-sans uppercase font-bold bg-rose-500/20 text-rose-400 border border-rose-500/30';
      colorTag.innerText = 'Қызыл ↑';
      targetDisplay.innerText = this.gorbovRedTarget;
    } else {
      colorTag.className = 'text-xs px-2 py-0.5 rounded-full font-sans uppercase font-bold bg-slate-800 text-slate-200 border border-slate-700';
      colorTag.innerText = 'Қара ↓';
      targetDisplay.innerText = this.gorbovBlackTarget;
    }
  },

  winGame() {
    clearInterval(this.timerInterval);
    this.active = false;
    const totalSec = parseFloat(((performance.now() - this.startTime) / 1000).toFixed(2));

    const baseXP = this.size * 12;
    const penalty = this.mistakes * 8;
    const earnedXP = Math.max(5, baseXP - penalty);

    uiHelpers.addXP(earnedXP, `Шульте ${this.size}×${this.size} аяқталды (${totalSec}с)!`);
    analyticsManager.recordRealActivity(`🔢 Шульте ${this.size}×${this.size} (${totalSec}с)`, appState.user.maxWPM, appState.user.ers, Math.max(50, 100 - this.mistakes * 10));
  }
};

/* =========================================================================
   MODULE 3: SACCADE & IT-TACHISTOSCOPE
   ========================================================================= */
const saccadeEngine = {
  subTab: 'pyramid',
  flashDuration: 120,
  currentSecretWord: '',

  init() {
    this.generatePyramid();
  },

  setSubTab(tab) {
    this.subTab = tab;
    document.getElementById('saccadePyramidView').classList.toggle('hidden', tab !== 'pyramid');
    document.getElementById('saccadeTachistoView').classList.toggle('hidden', tab !== 'tachisto');
    document.getElementById('subtab-pyramid').className = tab === 'pyramid' ? 'px-4 py-2 rounded-xl text-xs font-bold bg-brand-600 text-white shadow-md' : 'px-4 py-2 rounded-xl text-xs font-bold text-slate-300 hover:text-white';
    document.getElementById('subtab-tachisto').className = tab === 'tachisto' ? 'px-4 py-2 rounded-xl text-xs font-bold bg-brand-600 text-white shadow-md' : 'px-4 py-2 rounded-xl text-xs font-bold text-slate-300 hover:text-white';
  },

  generatePyramid() {
    const container = document.getElementById('pyramidListContainer');
    if (!container) return;
    container.innerHTML = '';
    const itSyllables = ['SQL', 'CPU', 'RAM', 'LAN', 'WAN', 'API', 'DOM', 'CSS', 'GIT', 'SSH', 'TCP', 'UDP', 'DNS', 'NPU', 'GPU', 'OOP'];
    for (let i = 0; i < 8; i++) {
      const row = document.createElement('div');
      row.className = 'flex items-center justify-between w-full border-b border-slate-800/80 pb-1.5';
      row.style.width = `${Math.min(100, 24 + i * 10)}%`;
      const left = itSyllables[Math.floor(Math.random() * itSyllables.length)];
      const right = Math.floor(10 + Math.random() * 89);
      row.innerHTML = `
        <span class="text-slate-200">${left}</span>
        <div class="w-2.5 h-2.5 rounded-full bg-rose-500 shadow shadow-rose-500"></div>
        <span class="text-cyber-teal">${right}</span>
      `;
      container.appendChild(row);
    }
    audioEngine.playBlip(540, 0.05);
  },

  setFlashDuration(ms) {
    this.flashDuration = parseInt(ms, 10);
    document.getElementById('tachistoDurationLabel').innerText = `${this.flashDuration} мс`;
  },

  triggerFlash() {
    const pool = ['алгоритм', 'компилятор', 'рекурсия', 'процессор', 'инкапсуляция', 'полиморфизм', 'транзакция', 'криптография', 'интерфейс', 'протокол', 'топология', 'массив'];
    this.currentSecretWord = pool[Math.floor(Math.random() * pool.length)];
    const box = document.getElementById('tachistoFlashBox');
    const inputGroup = document.getElementById('tachistoAnswerGroup');
    const input = document.getElementById('tachistoUserInput');

    box.innerText = this.currentSecretWord;
    audioEngine.playBlip(720, 0.03);

    setTimeout(() => {
      box.innerHTML = `<span class="text-slate-500 text-lg font-sans font-normal">Терминді жазыңыз...</span>`;
      inputGroup.classList.remove('hidden');
      input.value = '';
      input.focus();
    }, this.flashDuration);
  },

  verifyTachisto() {
    const input = document.getElementById('tachistoUserInput');
    const val = input.value.trim().toLowerCase();
    if (val === this.currentSecretWord.toLowerCase()) {
      audioEngine.playFanfare();
      uiHelpers.addXP(25, `Термин дәл танылды: «${this.currentSecretWord}»`);
      document.getElementById('tachistoFlashBox').innerHTML = `<span class="text-emerald-400 font-bold">✓ ${this.currentSecretWord}</span>`;
    } else {
      audioEngine.playError();
      uiHelpers.toast(`Қате! Дұрыс сөз: «${this.currentSecretWord}» (0 XP)`, false);
      document.getElementById('tachistoFlashBox').innerHTML = `<span class="text-rose-400 font-bold">✕ ${this.currentSecretWord}</span>`;
    }
    document.getElementById('tachistoAnswerGroup').classList.add('hidden');
  }
};

/* =========================================================================
   MODULE 4: PACER & METRONOME
   ========================================================================= */
const pacerEngine = {
  topic: 'algorithms',
  lpm: 30,
  bpm: 110,
  pacerActive: false,
  metroActive: false,
  pacerTimer: null,
  metroTimer: null,
  currentLine: 0,
  lines: [],

  init() {
    this.changeTopic(this.topic);
  },

  changeTopic(topicKey) {
    this.resetPacer();
    this.topic = topicKey;
    const rawText = multiLangData.kz.texts[topicKey] || multiLangData.kz.texts.algorithms;
    const container = document.getElementById('pacerTextBody');
    if (!container) return;

    this.lines = rawText.split(/(?<=[.!?])\s+/).filter(s => s.trim().length > 0);
    container.innerHTML = this.lines.map((s, idx) => `
      <p id="pacerLine-${idx}" class="pacer-line p-3 rounded-xl text-slate-300 cursor-pointer" onclick="pacerEngine.jumpToLine(${idx})">
        <span class="font-mono text-[10px] text-slate-500 mr-2">#${idx + 1}</span>${s}
      </p>
    `).join('');

    this.updateProgressUI();
  },

  jumpToLine(idx) {
    this.currentLine = idx;
    this.highlightCurrentLine();
    this.updateProgressUI();
  },

  setLPM(val) {
    this.lpm = parseInt(val, 10);
    document.getElementById('pacerLpmValue').innerText = this.lpm;
    const estWpm = this.lpm * 11;
    const badge = document.getElementById('pacerEstWpmBadge');
    if (badge) badge.innerText = `~${estWpm} WPM`;
  },

  setBPM(val) {
    this.bpm = parseInt(val, 10);
    document.getElementById('metroBpmValue').innerText = this.bpm;
    if (this.metroActive) {
      clearInterval(this.metroTimer);
      this.startMetronomeLoop();
    }
  },

  togglePacer() {
    this.pacerActive = !this.pacerActive;
    const btn = document.getElementById('pacerToggleBtn');
    const txt = document.getElementById('pacerBtnText');
    if (this.pacerActive) {
      txt.innerText = '⏸ Пейсерді кідірту (Бос орын)';
      btn.className = 'flex-1 py-3 rounded-2xl bg-rose-600 hover:bg-rose-500 text-white font-bold text-xs flex items-center justify-center gap-2 shadow-lg transition';
      this.runPacerStep();
    } else {
      txt.innerText = '▶️ Пейсерді жалғастыру (Бос орын)';
      btn.className = 'flex-1 py-3 rounded-2xl bg-gradient-to-r from-brand-600 to-indigo-600 text-white font-bold text-xs flex items-center justify-center gap-2 shadow-lg transition';
      clearTimeout(this.pacerTimer);
    }
  },

  highlightCurrentLine() {
    this.lines.forEach((_, idx) => {
      const el = document.getElementById(`pacerLine-${idx}`);
      if (!el) return;
      if (idx === this.currentLine) {
        el.className = 'pacer-line pacer-line-active p-3 rounded-xl font-medium';
        el.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
      } else {
        el.className = 'pacer-line pacer-line-dimmed p-3 rounded-xl text-slate-400';
      }
    });
  },

  updateProgressUI() {
    const total = this.lines.length;
    const cur = Math.min(total, this.currentLine + 1);
    const progTxt = document.getElementById('pacerLineProgress');
    const progBar = document.getElementById('pacerProgressBar');
    if (progTxt) progTxt.innerText = `${this.pacerActive ? cur : 0} / ${total}`;
    if (progBar) progBar.style.width = `${total > 0 ? Math.round((cur / total) * 100) : 0}%`;
  },

  runPacerStep() {
    if (!this.pacerActive) return;
    this.highlightCurrentLine();
    this.updateProgressUI();

    const delay = (60 / this.lpm) * 1000;
    this.pacerTimer = setTimeout(() => {
      this.currentLine++;
      if (this.currentLine >= this.lines.length) {
        this.resetPacer();
        appState.user.totalWordsRead += 140;
        uiHelpers.addXP(35, "Пейсер жаттығуы толық орындалды!");
        return;
      }
      this.runPacerStep();
    }, delay);
  },

  resetPacer() {
    clearTimeout(this.pacerTimer);
    this.pacerActive = false;
    this.currentLine = 0;
    const txt = document.getElementById('pacerBtnText');
    const btn = document.getElementById('pacerToggleBtn');
    if (txt) txt.innerText = '▶️ Пейсерді іске қосу (Бос орын)';
    if (btn) btn.className = 'flex-1 py-3 rounded-2xl bg-gradient-to-r from-brand-600 to-indigo-600 text-white font-bold text-xs flex items-center justify-center gap-2 shadow-lg transition';
    document.querySelectorAll('#pacerTextBody p').forEach(p => {
      p.className = 'pacer-line p-3 rounded-xl text-slate-200';
    });
    const progBar = document.getElementById('pacerProgressBar');
    if (progBar) progBar.style.width = '0%';
  },

  startMetronomeLoop() {
    const intervalMs = (60 / this.bpm) * 1000;
    const pulse = document.getElementById('metroVisualPulse');
    this.metroTimer = setInterval(() => {
      audioEngine.playMetronomeClick();
      if (pulse) {
        pulse.className = 'w-3 h-3 rounded-full bg-cyber-teal scale-150 shadow-lg shadow-cyber-teal transition-transform duration-75';
        setTimeout(() => {
          pulse.className = 'w-3 h-3 rounded-full bg-slate-700 scale-100 transition-transform duration-75';
        }, 90);
      }
    }, intervalMs);
  },

  toggleMetronome() {
    this.metroActive = !this.metroActive;
    const btn = document.getElementById('metroToggleBtn');
    const txt = document.getElementById('metroBtnText');
    if (this.metroActive) {
      txt.innerText = 'Метрономды өшіру (Белсенді)';
      btn.className = 'py-3 rounded-2xl bg-cyber-teal/20 text-cyber-teal font-bold text-xs flex items-center justify-center gap-2 border border-cyber-teal transition';
      this.startMetronomeLoop();
    } else {
      txt.innerText = 'Метрономды қосу';
      btn.className = 'py-3 rounded-2xl bg-slate-800 hover:bg-slate-700 text-white font-bold text-xs flex items-center justify-center gap-2 border border-slate-700 transition';
      clearInterval(this.metroTimer);
    }
  }
};

/* =========================================================================
   MODULE 5: WPM DIAGNOSTICS (5 ИНФОРМАТИКА МӘТІНІ + НАҚТЫ SUPABASE ЖАЗБА)
   ========================================================================= */
const diagnosticEngine = {
  currentTopic: 'topic1',
  startTime: null,
  timerInterval: null,
  readingSeconds: 0,
  totalWords: 0,

  init() {
    this.setTopic(this.currentTopic);
  },

  setTopic(topicKey) {
    this.currentTopic = topicKey;
    ['topic1', 'topic2', 'topic3', 'topic4', 'topic5'].forEach(key => {
      const btn = document.getElementById(`diagTab${key.charAt(0).toUpperCase() + key.slice(1)}`);
      if (btn) {
        btn.className = (key === topicKey)
          ? 'py-2.5 px-2 rounded-xl bg-brand-600 text-white shadow transition'
          : 'py-2.5 px-2 rounded-xl text-slate-400 hover:text-white transition';
      }
    });
    this.restart();
  },

  restart() {
    clearInterval(this.timerInterval);
    document.getElementById('diagStepReading').classList.remove('hidden');
    document.getElementById('diagStepQuiz').classList.add('hidden');
    document.getElementById('diagStepResults').classList.add('hidden');

    const diagData = multiLangData.kz.diagnostic[this.currentTopic] || multiLangData.kz.diagnostic.topic1;

    const headingEl = document.getElementById('diagCurrentHeading');
    if (headingEl) headingEl.innerText = diagData.title;

    const container = document.getElementById('diagPassageContainer');
    if (container) {
      container.innerHTML = diagData.text.split('\n\n').map(p => `<p class="leading-relaxed indent-6">${p.replace(/\n/g, '<br>')}</p>`).join('');
    }

    this.totalWords = diagData.text.split(/\s+/).filter(w => w.length > 0).length;
    const wordCountEl = document.getElementById('diagWordCountLabel');
    if (wordCountEl) wordCountEl.innerText = `${this.totalWords} сөз`;

    this.startTime = performance.now();
    document.getElementById('diagLiveTimer').innerText = '00:00';
    this.timerInterval = setInterval(() => {
      const sec = Math.floor((performance.now() - this.startTime) / 1000);
      const m = String(Math.floor(sec / 60)).padStart(2, '0');
      const s = String(sec % 60).padStart(2, '0');
      document.getElementById('diagLiveTimer').innerText = `${m}:${s}`;
    }, 500);
  },

  finishReading() {
    const elapsedSec = (performance.now() - this.startTime) / 1000;
    if (elapsedSec < 4) {
      audioEngine.playError();
      uiHelpers.toast("Тым тез! Мәтінді кемінде бірнеше секунд мұқият оқып шығыңыз.", false);
      return;
    }

    clearInterval(this.timerInterval);
    this.readingSeconds = Math.max(5, elapsedSec);
    document.getElementById('diagStepReading').classList.add('hidden');
    document.getElementById('diagStepQuiz').classList.remove('hidden');

    const diagData = multiLangData.kz.diagnostic[this.currentTopic] || multiLangData.kz.diagnostic.topic1;
    const container = document.getElementById('diagQuizList');
    container.innerHTML = diagData.questions.map((item, qIdx) => `
      <div class="bg-slate-950 border border-slate-800 p-4 sm:p-5 rounded-2xl shadow-sm">
        <p class="font-bold text-sm text-slate-100 mb-3">${qIdx + 1}. ${item.q}</p>
        <div class="space-y-2">
          ${item.opts.map((opt, oIdx) => `
            <label class="flex items-center gap-3 p-2.5 rounded-xl hover:bg-slate-900 cursor-pointer text-xs font-semibold text-slate-300 border border-transparent hover:border-slate-800 transition">
              <input type="radio" name="diagQuestion_${qIdx}" value="${oIdx}" class="w-4 h-4 text-brand-600 focus:ring-0">
              <span>${opt}</span>
            </label>
          `).join('')}
        </div>
      </div>
    `).join('');
  },

  evaluateAnswers() {
    const diagData = multiLangData.kz.diagnostic[this.currentTopic] || multiLangData.kz.diagnostic.topic1;
    let correctCount = 0;
    let reviewHtml = '';

    diagData.questions.forEach((q, idx) => {
      const selected = document.querySelector(`input[name="diagQuestion_${idx}"]:checked`);
      const userAns = selected ? parseInt(selected.value, 10) : -1;
      const isOk = userAns === q.ans;
      if (isOk) correctCount++;

      const userAnsText = userAns !== -1 ? q.opts[userAns] : "Белгіленбеді";
      const rightAnsText = q.opts[q.ans];

      reviewHtml += `
        <div class="p-3.5 rounded-xl border ${isOk ? 'bg-emerald-950/25 border-emerald-500/30' : 'bg-rose-950/25 border-rose-500/30'} text-xs">
          <div class="font-bold text-white mb-1">${idx + 1}. ${q.q}</div>
          <div class="${isOk ? 'text-emerald-400' : 'text-rose-400'} font-semibold">
            ${isOk ? '✓ Сіздің жауабыңыз дұрыс:' : '✕ Сіздің жауабыңыз:'} ${userAnsText}
          </div>
          ${!isOk ? `<div class="text-cyber-teal font-semibold mt-1">💡 Дұрыс жауап: ${rightAnsText}</div>` : ''}
        </div>
      `;
    });

    const compPct = Math.round((correctCount / diagData.questions.length) * 100);
    const rawWpm = Math.min(900, Math.round((this.totalWords / this.readingSeconds) * 60));
    const ers = Math.round(rawWpm * (compPct / 100));

    document.getElementById('diagStepQuiz').classList.add('hidden');
    document.getElementById('diagStepResults').classList.remove('hidden');

    document.getElementById('diagResRawWpm').innerText = rawWpm;
    document.getElementById('diagResComp').innerText = `${compPct}%`;
    document.getElementById('diagResScoreDetails').innerText = `${correctCount} / ${diagData.questions.length} дұрыс`;
    document.getElementById('diagResERS').innerText = ers;
    document.getElementById('diagAnswerReviewList').innerHTML = reviewHtml;

    let earnedXP = 0;
    const rec = document.getElementById('diagRecommendation');
    const xpBadge = document.getElementById('diagEarnedXpBadge');

    if (compPct >= 80) {
      earnedXP = correctCount * 12;
      rec.innerText = `🏆 Өте жоғары нәтиже! 10 сұрақтың ${correctCount}-іне дұрыс жауап бердіңіз (${compPct}%). Нақты тиімді жылдамдығыңыз: ${ers} ERS.`;
      xpBadge.innerText = `+${earnedXP} XP есептелді (Жоғары дәлдік бонусы!)`;
      uiHelpers.addXP(earnedXP, `Диагностика үздік тапсырылды (${compPct}%)!`);
    } else if (compPct >= 50) {
      earnedXP = correctCount * 8;
      rec.innerText = `👍 Жақсы нәтиже (${correctCount}/10 дұрыс). Дегенмен қате кеткен сұрақтарды төмендегі талдаудан қарап шығыңыз.`;
      xpBadge.innerText = `+${earnedXP} XP есептелді`;
      uiHelpers.addXP(earnedXP, `Диагностика тапсырылды (${compPct}%)`);
    } else {
      earnedXP = 0;
      rec.innerText = `⚠️ Назар аударыңыз: Мәтінді түсіну деңгейі тым төмен (${compPct}%, тек ${correctCount}/10 дұрыс). Түсіну 50%-дан төмен болғандықтан 0 XP берілді. Мәтінді асықпай қайта оқыңыз!`;
      xpBadge.innerText = `0 XP (Түсіну деңгейі 50%-дан төмен)`;
      audioEngine.playError();
      uiHelpers.toast("Түсіну 50%-дан төмен: XP берілген жоқ!", false);
    }

    if (compPct >= 50) {
      appState.user.wpmHistory.push(ers);
      if (appState.user.wpmHistory.length > 8) appState.user.wpmHistory.shift();
      appState.user.totalWordsRead += this.totalWords;
      if (rawWpm > appState.user.maxWPM) appState.user.maxWPM = rawWpm;
      if (ers > appState.user.ers) appState.user.ers = ers;
    }

    // Шынайы нәтижені Supabase-ке жіберу
    const topicLabels = {
      topic1: '1. Алгоритм',
      topic2: '2. Желілер',
      topic3: '3. ДҚ & SQL',
      topic4: '4. Қауіпсіздік',
      topic5: '5. AI & ML'
    };
    analyticsManager.recordRealActivity(`🎯 Тест: ${topicLabels[this.currentTopic] || 'Диагностика'}`, rawWpm, ers, compPct);
  }
};

/* =========================================================================
   LOCAL STORAGE & CLEAN RESET (ЖАЛҒАН ЖАЗБАЛАРДЫ БІРЖОЛА ТАЗАРТУ)
   ========================================================================= */
const storageManager = {
  key: 'neuroread_real_clean_v5',
  save() {
    try {
      const payload = {
        user: appState.user,
        loginAuditLogs: appState.loginAuditLogs
      };
      localStorage.setItem(this.key, JSON.stringify(payload));
    } catch (e) {}
  },
  load() {
    try {
      // Ескі фейк деректер сақталған кілттерді автоматты түрде өшіру
      localStorage.removeItem('neuroread_pro_full_v3');
      localStorage.removeItem('neuroread_it_pro_v4');

      const raw = localStorage.getItem(this.key);
      if (raw) {
        const data = JSON.parse(raw);
        if (data.user) appState.user = { ...appState.user, ...data.user };
        if (data.loginAuditLogs) appState.loginAuditLogs = data.loginAuditLogs;
      }
    } catch (e) {}
  },
  exportData() {
    const dataStr = "data:text/json;charset=utf-8," + encodeURIComponent(JSON.stringify(appState, null, 2));
    const a = document.createElement('a');
    a.href = dataStr;
    a.download = `neuroread_backup_${new Date().toISOString().slice(0, 10)}.json`;
    document.body.appendChild(a);
    a.click();
    a.remove();
    uiHelpers.toast("JSON деректер қоры сақталды");
  },
  resetData() {
    localStorage.clear();
    window.location.reload();
  }
};

/* =========================================================================
   I18N & NEURO-WARMUP VIDEO MANAGER
   ========================================================================= */
const i18n = {
  setLanguage(langCode) {
    appState.lang = langCode;
    document.getElementById('langSelect').value = langCode;
    const dict = multiLangData[langCode].ui;
    document.querySelectorAll('[data-i18n]').forEach(el => {
      const key = el.getAttribute('data-i18n');
      if (dict[key]) el.innerText = dict[key];
    });
    uiHelpers.toast(`Тіл: ${langCode.toUpperCase()}`);
  }
};

const neuroWarmup = {
  videos: {
    eyes: {
      file: "videos/eyes.mp4",
      fallback: "eyes.mp4",
      hint: "💡 Көз жаттығуы: Басыңызды қозғалтпай, экрандағы нүктені тек көзбен қадағалаңыз."
    },
    fingers: {
      file: "videos/fingers.mp4",
      fallback: "fingers.mp4",
      hint: "💡 Саусақ жаттығуы: Бейнеге қарап екі қолмен қимылдарды бірдей қайталаңыз."
    },
    brain: {
      file: "videos/brain.mp4",
      fallback: "brain.mp4",
      hint: "💡 Зейін фокусы: Тынысыңызды реттеп, барлық зейінді орталық нүктеге шоғырландырыңыз."
    }
  },
  currentCategory: 'eyes',

  open() {
    modals.open('neuroWarmupModal');
    setTimeout(() => this.selectVideo(this.currentCategory), 100);
  },

  selectVideo(category) {
    this.currentCategory = category;
    const player = document.getElementById('warmupVideoPlayer');
    const hint = document.getElementById('warmupHintText');

    ['Eyes', 'Fingers', 'Brain'].forEach(name => {
      const btn = document.getElementById(`tabWarmup${name}`);
      if (btn) {
        btn.className = (name.toLowerCase() === category)
          ? 'py-2 rounded-xl bg-brand-600 text-white shadow transition'
          : 'py-2 rounded-xl text-slate-400 hover:text-white transition';
      }
    });

    if (this.videos[category] && player) {
      const vidData = this.videos[category];
      player.muted = true;
      player.pause();
      player.onerror = () => {
        if (!player.dataset.triedFallback) {
          player.dataset.triedFallback = "true";
          player.src = vidData.fallback;
          player.load();
          player.play().catch(() => {});
        }
      };
      delete player.dataset.triedFallback;
      player.src = vidData.file;
      player.load();
      player.play().catch(() => {});
      if (hint) hint.innerText = vidData.hint;
    }
  },

  close() {
    const player = document.getElementById('warmupVideoPlayer');
    if (player) {
      player.pause();
      player.currentTime = 0;
    }
    modals.close('neuroWarmupModal');
  }
};

/* =========================================================================
   KEYBOARD SHORTCUTS & APP INITIALIZATION
   ========================================================================= */
window.addEventListener('keydown', (e) => {
  if (['INPUT', 'TEXTAREA', 'SELECT'].includes(e.target.tagName)) return;
  if (e.code === 'Space') {
    e.preventDefault();
    if (appState.currentRoute === 'rsvp') rsvpEngine.togglePlay();
    if (appState.currentRoute === 'pacer') pacerEngine.togglePacer();
  } else if (e.code === 'ArrowUp') {
    e.preventDefault();
    rsvpEngine.setWPM(Math.min(1000, rsvpEngine.wpm + 25));
  } else if (e.code === 'ArrowDown') {
    e.preventDefault();
    rsvpEngine.setWPM(Math.max(150, rsvpEngine.wpm - 25));
  } else if (e.code === 'ArrowLeft') {
    e.preventDefault();
    rsvpEngine.skipWords(-15);
  } else if (e.code === 'ArrowRight') {
    e.preventDefault();
    rsvpEngine.skipWords(15);
  }
});

window.onload = function() {
  storageManager.load();
  authManager.init();
  rsvpEngine.init();
  pacerEngine.init();
  analyticsManager.fetchFromSupabase();
};